function minNonZeroProduct(p) {
  const MOD = 1000000007n;
  const largest = (1n << BigInt(p)) - 1n;
  const pairs = largest / 2n;
  let base = (largest - 1n) % MOD;
  let exponent = pairs;
  let power = 1n;

  while (exponent > 0n) {
    if (exponent & 1n) {
      power = power * base % MOD;
    }
    base = base * base % MOD;
    exponent >>= 1n;
  }
  return Number(largest % MOD * power % MOD);
}

