function minNonZeroProduct(p) {
  const MOD = 1000000007;
  const n = 2 ** p - 1;
  if (p <= 3) {
    // Swaps can rearrange each bit column freely, but never change how many ones it holds.
    const half = 2 ** (p - 1);
    const masks = [];
    for (let m = 0; m < (1 << n); m++) {
      let ones = 0;
      for (let b = 0; b < n; b++) if (m & (1 << b)) ones++;
      if (ones === half) masks.push(m);
    }
    let best = Infinity;
    const values = new Array(n).fill(0);
    const place = (bit) => {
      if (bit === p) {
        let product = 1;
        for (const v of values) product *= v;
        if (product > 0) best = Math.min(best, product);
        return;
      }
      for (const m of masks) {
        for (let i = 0; i < n; i++) if (m & (1 << i)) values[i] += 2 ** bit;
        place(bit + 1);
        for (let i = 0; i < n; i++) if (m & (1 << i)) values[i] -= 2 ** bit;
      }
    };
    place(0);
    return best % MOD;
  }
  if (p <= 16) {
    // Build the optimal list explicitly: x and n - x become 1 and n - 1.
    const list = Array.from({ length: n }, (_, i) => i + 1);
    for (let x = 1; x < n - x; x++) {
      list[x - 1] = 1;
      list[n - x - 1] = n - 1;
    }
    let product = 1;
    for (const v of list) product = product * v % MOD;
    return product;
  }
  // (n - 1)^(2^(p-1) - 1) is the product of (n - 1)^(2^i) for i = 0 .. p - 2.
  const M = BigInt(MOD);
  const top = 2n ** BigInt(p) - 1n;
  let square = (top - 1n) % M;
  let product = top % M;
  for (let i = 0; i <= p - 2; i++) {
    product = product * square % M;
    square = square * square % M;
  }
  return Number(product);
}

